const cfg=window.TOURNAMENT_SUPABASE_CONFIG||{};
// ضع هنا رابط CSV المنشور من Google Sheets (لا تضع رابط التعديل العادي).
const GOOGLE_SHEET_CSV_URL = "";
let sheetPlayers=[], sheetLoaded=false;
const supabaseReady=!!(window.supabase&&cfg.url&&cfg.anonKey&&!cfg.url.includes('PASTE_')&&!cfg.anonKey.includes('PASTE_'));
const sb=supabaseReady?window.supabase.createClient(cfg.url,cfg.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
let data={groups:[],teams:[],players:[],matches:[],events:[],lineups:[]},currentUser=null,currentRole=null,cloudMode=false,activeFilter='all';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const setText=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
function toast(msg){const e=document.getElementById('toast');if(!e){alert(msg);return}e.textContent=msg;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3500)}
const team=id=>data.teams.find(t=>String(t.id)===String(id))||{id:'',name:'فريق غير معروف',group_id:'',logo_url:'',short_name:'؟'};
const player=id=>data.players.find(p=>String(p.id)===String(id));
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++;}else if(c==='"'){quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(cell.length||row.length){row.push(cell);rows.push(row);}return rows;}
function normalizeHeader(s){return String(s||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[أإآٱ]/g,'ا').replace(/[\s_\-.,:؛،?!؟📸]/g,'');}
function publicPhotoURL(value){const u=String(value||'').trim();if(!u)return '';let m=u.match(/drive\.google\.com\/(?:file\/d\/|drive\/u\/\d+\/folders\/|open\?[^#]*?id=|uc\?[^#]*?id=|thumbnail\?[^#]*?id=)([A-Za-z0-9_-]+)/);if(!m){try{const parsed=new URL(u);if(parsed.hostname.endsWith('drive.google.com'))m=[null,parsed.searchParams.get('id')||''];}catch(_){}}if(m&&m[1])return 'https://drive.google.com/uc?export=view&id='+m[1];return u;}
async function loadSheetPlayers(){if(!GOOGLE_SHEET_CSV_URL||GOOGLE_SHEET_CSV_URL.includes('PASTE_CSV_LINK_HERE'))return;try{const res=await fetch(GOOGLE_SHEET_CSV_URL,{cache:'no-store'});if(!res.ok)throw new Error('CSV HTTP '+res.status);const rows=parseCSV((await res.text()).replace(/^\uFEFF/,''));if(rows.length<2)return;const headers=rows[0].map(normalizeHeader);const nameIndex=headers.findIndex(h=>h.includes(normalizeHeader('الإسم الكامل'))||h.includes(normalizeHeader('الاسم الكامل')));const photoIndex=headers.findIndex(h=>h.includes(normalizeHeader('حمّل صورة شخصية واضحة لك'))||h.includes(normalizeHeader('صورة شخصية')));if(nameIndex<0||photoIndex<0)throw new Error('تعذر العثور على عمودي الاسم الكامل والصورة في CSV');const imported=[];for(let i=1;i<rows.length;i++){const full_name=String(rows[i][nameIndex]||'').trim(),photo_url=publicPhotoURL(rows[i][photoIndex]);if(!full_name)continue;imported.push({id:'sheet-'+i+'-'+full_name.toLowerCase().replace(/\s+/g,'-'),team_id:null,full_name,shirt_number:null,photo_url,active:true,sheet_imported:true});}sheetPlayers=imported;sheetLoaded=true;data.players=data.players.filter(p=>!p.sheet_imported).concat(sheetPlayers);console.info('تم تحميل لاعبي Google Sheets:',sheetPlayers.length);}catch(err){
 // Google Sheets may redirect or block browser fetch with CORS, especially when the site is opened via file://.
 // Treat sheet import as optional: keep Supabase data and the rest of the admin usable.
 sheetLoaded=true; // Avoid repeating a failing request every time loadCloud/init runs.
 console.warn('تعذر تحميل لاعبي Google Sheets (لن يتوقف الموقع بسبب ذلك):',err);
 const notice=document.getElementById('sheetNotice');
 if(notice)notice.textContent='تعذر جلب التسجيلات من Google Sheets. بيانات الموقع الأساسية باقية خدامة؛ تأكد أن الورقة منشورة للويب وأن رابط CSV صحيح، وافتح الموقع عبر Live Server أو الاستضافة بدل file://.';
 }}

const match=id=>data.matches.find(m=>String(m.id)===String(id));
function teamLogo(t,large=false){return t.logo_url?`<img class="team-logo ${large?'large':''}" src="${esc(t.logo_url)}" alt="لوغو ${esc(t.name)}" loading="lazy" onerror="this.onerror=null;this.outerHTML='<span class=\'team-logo no-image ${large?'large':''}\'>${esc((t.short_name||t.name||'ف').slice(0,2))}</span>'">`:`<span class="team-logo no-image ${large?'large':''}">${esc((t.short_name||t.name||'ف').slice(0,2))}</span>`}
function teamLink(t){return `<a class="team-link" href="team.html?id=${encodeURIComponent(t.id)}">${teamLogo(t)}<span>${esc(t.name)}</span></a>`}
function playerLink(p){return p?`<a class="player-link" href="player.html?id=${encodeURIComponent(p.id)}">${playerPhoto(p)}<span>${esc(p.full_name)}</span></a>`:'لاعب غير محدد'}
function scheduledReached(m){return !!m.scheduled_at && Date.now()>=new Date(m.scheduled_at).getTime()}
function phaseOf(m){return m?.phase||m?.match_phase||'upcoming'}
function penaltyScoreMarkup(m){const h=m?.penalty_home_score,a=m?.penalty_away_score;return h!==null&&h!==undefined&&a!==null&&a!==undefined?`<small class="penalty-score">(${Number(h)} : ${Number(a)})</small>`:''}
function mainScoreMarkup(m){return `${Number(m.home_score)||0} : ${Number(m.away_score)||0}${penaltyScoreMarkup(m)}`}
function tiedMatch(m){return !!m&&Number(m.home_score||0)===Number(m.away_score||0)}
function liveElapsedSeconds(m){if(!m)return 0;const phase=phaseOf(m);const anchor=m.phase_started_at?new Date(m.phase_started_at).getTime():0;const running=m.status==='live'&&['first_half','second_half','extra_time'].includes(phase)&&anchor>0?Math.max(0,Math.floor((Date.now()-anchor)/1000)):0;const stored=Number(m.phase_elapsed_seconds)||0;return Math.max(0,stored+running)}
function liveMinute(m){if(!m)return 0;const phase=phaseOf(m);const elapsed=liveElapsedSeconds(m);if(phase==='first_half')return Math.min(20,Math.floor(elapsed/60));if(phase==='half_time')return 20;if(phase==='second_half')return Math.min(45,20+Math.floor(elapsed/60));if(phase==='extra_time')return Math.min(90,45+Math.floor(elapsed/60));if(phase==='penalties')return 45;return Math.min(45,Number(m.current_minute??m.minute)||0)}
function displayMinute(m){const n=liveMinute(m);if(phaseOf(m)==='extra_time'&&n>45)return `45+${n-45}`;return String(n)}
function displayTimer(m){const phase=phaseOf(m);if(!m||m.status!=='live'||!['first_half','second_half','extra_time'].includes(phase))return '';const base=phase==='second_half'?1200:phase==='extra_time'?2700:0;const cap=phase==='first_half'?1200:phase==='second_half'?2700:5400;const seconds=Math.min(base+liveElapsedSeconds(m),cap);const mm=String(Math.floor(seconds/60)).padStart(2,'0'),ss=String(seconds%60).padStart(2,'0');return `${mm}:${ss}`}
function displayEventMinute(m){const n=liveMinute(m);const phase=phaseOf(m);if(phase==='first_half'&&n>=20)return '20+';if(phase==='second_half'&&n>=45)return '45+';if(phase==='extra_time'&&n>45)return `45+${n-45}`;return String(n)}
function playerPhoto(p){return p.photo_url?`<img class="player-photo" src="${esc(p.photo_url)}" alt="${esc(p.full_name)}" loading="lazy" onerror="this.onerror=null;this.classList.add('no-image');this.replaceWith(Object.assign(document.createElement('span'),{className:'player-photo no-image',textContent:'ل'}));">`:`<div class="player-photo no-image">${esc((p.full_name||'ل').slice(0,1))}</div>`}
function formatDate(value){if(!value)return'التاريخ يحدد لاحقاً';const d=new Date(value);return Number.isNaN(d.getTime())?esc(value):new Intl.DateTimeFormat('ar-MA',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
function statusLabel(m){const ph=phaseOf(m);if(m.status==='live'&&ph&&ph!=='upcoming')return ({first_half:'الشوط الأول',half_time:'استراحة بين الشوطين',second_half:'الشوط الثاني',extra_time:'الأشواط الإضافية',penalties:'ركلات الترجيح'})[ph]||'مباشرة';return m.status==='live'?'مباشرة':m.status==='finished'?'انتهت':m.status==='postponed'?'تأجلت':m.status==='cancelled'?'ألغيت':'قادمة'}
function stageLabel(m){return m.stage==='semifinal'?'نصف النهائي':m.stage==='final'?'النهائي':`المجموعة ${m.group_id||''}`}
function eventLabel(e){return ({goal:`هدف${e.goal_method==='penalty'?' من ضربة جزاء':e.goal_method==='free_kick'?' من ركلة حرة':''}`,own_goal:'هدف عكسي',yellow:'بطاقة صفراء',red:'بطاقة حمراء',second_yellow:'بطاقة صفراء ثانية وطرد',injury:'إصابة'})[e.type||e.event_type]||'حدث'}
function goalEvents(){return data.events.filter(e=>(e.type||e.event_type)==='goal')}
function renderStats(){const teams=data.teams.length,matches=data.matches.length,players=data.players.filter(p=>p.active!==false).length,goals=goalEvents().length+data.events.filter(e=>(e.type||e.event_type)==='own_goal').length;setText('teamCount',teams);setText('matchCount',matches);setText('playerCount',players);setText('goalCount',goals);setText('heroTeamCount',teams);setText('heroMatchCount',matches);setText('heroGoalCount',goals)}
function renderMatches(){const el=document.getElementById('matchList');if(!el)return;let rows=data.matches.filter(m=>activeFilter==='all'||m.status===activeFilter).sort((a,b)=>new Date(a.scheduled_at||'2999-01-01')-new Date(b.scheduled_at||'2999-01-01'));if(document.querySelector('.hero'))rows=rows.slice(0,4);if(!rows.length){el.innerHTML='<div class="empty">لم يتم الإعلان عن المباريات بعد.</div>';return}el.innerHTML=rows.map(m=>{const h=team(m.home_team_id),a=team(m.away_team_id),upcoming=m.status==='upcoming'||m.status==='postponed'||!m.status,score=upcoming?'VS':mainScoreMarkup(m),time=m.scheduled_at?formatDate(m.scheduled_at):'سيُعلن عن الموعد لاحقاً';return `<a class="match-card match-card-link" data-live-match="${esc(m.id)}" href="match.html?id=${encodeURIComponent(m.id)}"><div class="match-meta"><span>${esc(stageLabel(m))}</span><span class="status ${esc(m.status||'upcoming')}">${statusLabel(m)}</span></div><div class="match-teams"><div class="match-team"><span class="team-link">${teamLogo(h)}<span>${esc(h.name)}</span></span></div><div class="score">${score}</div><div class="match-team"><span class="team-link">${teamLogo(a)}<span>${esc(a.name)}</span></span></div></div><div class="match-date">${esc(time)}</div>${m.status==='live'?`<div class="live-timer">● ${esc(displayTimer(m))} <small>${esc(displayMinute(m))}′</small></div>`:''}<div class="match-open-label">عرض تفاصيل المباراة ←</div></a>`}).join('')}
function computeStandings(groupId){const rows=data.teams.filter(t=>String(t.group_id)===String(groupId)).map(t=>({team:t,played:0,w:0,d:0,l:0,gf:0,ga:0,pts:0})),byId=new Map(rows.map(r=>[String(r.team.id),r]));data.matches.filter(m=>(m.stage||'groups')==='groups'&&String(m.group_id)===String(groupId)&&m.status==='finished').forEach(m=>{const h=byId.get(String(m.home_team_id)),a=byId.get(String(m.away_team_id));if(!h||!a)return;const hs=Number(m.home_score)||0,as=Number(m.away_score)||0;h.played++;a.played++;h.gf+=hs;h.ga+=as;a.gf+=as;a.ga+=hs;if(hs>as){h.w++;h.pts+=3;a.l++}else if(hs<as){a.w++;a.pts+=3;h.l++}else{h.d++;a.d++;h.pts++;a.pts++}});return rows.sort((a,b)=>b.pts-a.pts||b.gf-a.gf||(b.gf-b.ga)-(a.gf-a.ga)||a.team.name.localeCompare(b.team.name,'ar'))}
function renderStandings(){const el=document.getElementById('standingsList');if(!el)return;el.innerHTML=data.groups.map(g=>{const rows=computeStandings(g.id);return `<article class="standings-card"><h3>${esc(g.name)} <span class="group-tag">${rows.length} فرق</span></h3><div class="table-wrap"><table><thead><tr><th>#</th><th>الفريق</th><th>لعب</th><th>له</th><th>عليه</th><th>الفارق</th><th>النقاط</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="rank">${i+1}</td><td class="team-name-cell">${teamLink(r.team)}</td><td>${r.played}</td><td>${r.gf}</td><td>${r.ga}</td><td>${r.gf-r.ga}</td><td><strong>${r.pts}</strong></td></tr>`).join('')||'<tr><td colspan="7">لا توجد فرق مسجلة في هذه المجموعة.</td></tr>'}</tbody></table></div></article>`}).join('')||'<div class="empty">لم تتم إضافة المجموعات بعد.</div>'}
function renderTeams(){const el=document.getElementById('teamList');if(el){el.innerHTML=data.teams.map(t=>`<a class="team-card" href="team.html?id=${encodeURIComponent(t.id)}">${teamLogo(t,true)}<div><strong>${esc(t.name)}</strong><small>${esc(data.groups.find(g=>String(g.id)===String(t.group_id))?.name||'المجموعة غير محددة')}</small></div></a>`).join('')||'<div class="empty">لم يتم تسجيل الفرق بعد.</div>'}setText('teamCount',data.teams.length);const reg=document.getElementById('registeredTeams');if(reg)reg.innerHTML=data.teams.map(t=>`<a class="team-card" href="team.html?id=${encodeURIComponent(t.id)}">${teamLogo(t,true)}<div><strong>${esc(t.name)}</strong><small>${esc(data.groups.find(g=>String(g.id)===String(t.group_id))?.name||'المجموعة غير محددة')} · ${data.players.filter(p=>String(p.team_id)===String(t.id)).length} لاعب</small></div></a>`).join('')||'<div class="empty">لا توجد تسجيلات بعد.</div>'}
function playerGoalCount(p){return goalEvents().filter(e=>String(e.player_id||'')===String(p.id)||(!e.player_id&&e.player_name===p.full_name&&String(e.team_id)===String(p.team_id))).length}
function renderTeamDetail(){const el=document.getElementById('teamDetail');if(!el)return;const id=new URLSearchParams(location.search).get('id'),t=data.teams.find(x=>String(x.id)===String(id));if(!t){el.innerHTML='<div class="empty">الفريق غير موجود أو لم يتم تسجيله.</div>';return}const players=data.players.filter(p=>String(p.team_id)===String(t.id)&&p.active!==false);el.innerHTML=`<section class="team-detail-head">${teamLogo(t,true)}<div><h1>${esc(t.name)}</h1><p>${esc(data.groups.find(g=>String(g.id)===String(t.group_id))?.name||'المجموعة غير محددة')} · ${players.length} لاعب مسجل</p></div></section><section class="section-block team-lineup-section"><div class="section-heading"><div><h2>تشكيلة الفريق</h2><p>الخطة الأساسية · خمسة لاعبين ميدانيين</p></div></div>${(()=>{const rows=data.lineups.filter(x=>String(x.team_id)===String(t.id)).sort((a,b)=>Number(a.slot)-Number(b.slot));const formation=rows[0]?.formation||'2-2-1';const parts=formation.split('-').map(Number);let pos=0;const groups=parts.map(n=>{const current=rows.slice(pos,pos+n);pos+=n;return {n,players:current}}).reverse();return `<div class="team-lineup-pitch"><div class="pitch-markings" aria-hidden="true"><span class="pitch-half-line"></span><span class="pitch-center-circle"></span><span class="pitch-box pitch-box-top"></span><span class="pitch-box pitch-box-bottom"></span></div><div class="lineup-formation-label">الخطة ${esc(formation)}</div><div class="team-lineup-rows">${groups.map(({n,players:current})=>`<div class="team-lineup-row" style="--lineup-count:${n}">${current.map(x=>{const pl=player(x.player_id);return pl?`<a class="team-lineup-player" href="player.html?id=${encodeURIComponent(pl.id)}">${playerPhoto(pl)}<span>${esc(pl.full_name)}</span></a>`:''}).join('')||'<span class="lineup-empty">—</span>'}</div>`).join('')}</div>${rows.length?'':'<span class="lineup-empty">لم تحدد التشكيلة بعد</span>'}</div>`})()}</section><section class="player-stats-grid"><article><strong>${data.matches.filter(m=>m.status==='finished'&&(String(m.home_team_id)===String(t.id)||String(m.away_team_id)===String(t.id))).length}</strong><span>المباريات</span></article><article><strong>${data.events.filter(e=>String(e.team_id)===String(t.id)&&(e.type==='goal'||e.type==='own_goal')).length}</strong><span>الأهداف من الأحداث</span></article><article><strong>${data.events.filter(e=>String(e.team_id)===String(t.id)&&e.type==='yellow').length}</strong><span>البطاقات الصفراء</span></article></section><section class="section-block"><div class="section-heading"><div><h2>لاعبو الفريق</h2><p>الأسماء والصور والأهداف المسجلة.</p></div></div><div class="player-grid">${players.map(p=>`<a href="player.html?id=${encodeURIComponent(p.id)}" class="player-card player-card-link">${playerPhoto(p)}<strong>${esc(p.full_name)}</strong><small>لاعب</small><div class="player-stats"><span>${playerGoalCount(p)} هدف</span><span>${data.events.filter(e=>String(e.assist_player_id||'')===String(p.id)).length} أسيست</span></div></a>`).join('')||'<div class="empty">لم يتم تسجيل لاعبي هذا الفريق بعد.</div>'}</div></section><section class="section-block"><h2>سجل المباريات</h2><div class="match-list">${data.matches.filter(m=>String(m.home_team_id)===String(t.id)||String(m.away_team_id)===String(t.id)).map(m=>`<a class="match-card" href="match.html?id=${encodeURIComponent(m.id)}"><div class="match-teams"><span>${esc(team(m.home_team_id).name)}</span><strong>${m.status==='upcoming'?'VS':mainScoreMarkup(m)}</strong><span>${esc(team(m.away_team_id).name)}</span></div><small>${esc(formatDate(m.scheduled_at))}</small></a>`).join('')||'<p>لا توجد مباريات مسجلة.</p>'}</div></section>`}
function statRows(kind){let counts={};if(kind==='goals'){goalEvents().forEach(e=>{const p=player(e.player_id),name=p?.full_name||e.player_name;if(!name)return;const key=p?.id||`${name}|${e.team_id}`;if(!counts[key])counts[key]={name,team:team(e.team_id),count:0};counts[key].count++})}else if(kind==='assists'){data.events.filter(e=>e.assist_player_id||e.assist_player_name).forEach(e=>{const p=player(e.assist_player_id),name=p?.full_name||e.assist_player_name;if(!name)return;const key=p?.id||`${name}|${e.team_id}`;if(!counts[key])counts[key]={name,team:team(p?.team_id||e.team_id),count:0};counts[key].count++})}return Object.values(counts).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name,'ar')).slice(0,5)}
function fillStatTable(id,rows,label,empty){const el=document.getElementById(id);if(!el)return;el.innerHTML=rows.map((r,i)=>`<tr><td class="rank">${i+1}</td><td>${esc(r.name)}</td><td>${teamLink(r.team)}</td><td><strong>${r.count}${label}</strong></td></tr>`).join('')||`<tr><td colspan="4">${empty}</td></tr>`}
function renderPlayerDetail(){const el=document.getElementById('playerDetail');if(!el)return;const id=new URLSearchParams(location.search).get('id'),p=player(id);if(!p){el.innerHTML='<div class="empty">اللاعب غير موجود.</div>';return}const ev=data.events.filter(e=>String(e.player_id)===String(p.id)),goals=ev.filter(e=>['goal','own_goal'].includes(e.type||e.event_type)).length,cards=ev.filter(e=>['yellow','red','second_yellow'].includes(e.type||e.event_type)).length,assists=data.events.filter(e=>String(e.assist_player_id||'')===String(p.id)).length;el.innerHTML=`<section class="player-profile">${playerPhoto(p)}<div><h1>${esc(p.full_name)}</h1><p>${teamLink(team(p.team_id))}</p><small>${p.shirt_number?'رقم القميص '+esc(p.shirt_number):'لاعب'}</small></div></section><section class="player-stats-grid"><article><strong>${goals}</strong><span>الأهداف</span></article><article><strong>${assists}</strong><span>الأسيست</span></article><article><strong>${cards}</strong><span>البطاقات</span></article></section><section class="section-block"><h2>أحداث اللاعب</h2>${ev.map(e=>`<div class="event-item"><span>${esc(e.minute??'—')}′</span><span>${esc(eventLabel(e))}</span><a href="match.html?id=${encodeURIComponent(e.match_id)}">${esc(team(e.team_id).name)}</a></div>`).join('')||'<p>لا توجد أحداث مسجلة لهذا اللاعب بعد.</p>'}</section>`}
function renderScorers(){fillStatTable('scorersList',statRows('goals'),'','ستظهر الإحصائيات بعد تسجيل الأهداف.');fillStatTable('assistsList',statRows('assists'),'','ستظهر صناعة الأهداف بعد تسجيل الأسيست.');const cards=data.events.filter(e=>['yellow','red','second_yellow'].includes(e.type||e.event_type));const rows=data.players.filter(p=>p.team_id).map(p=>({name:p.full_name,team:team(p.team_id),count:cards.filter(e=>String(e.player_id||'')===String(p.id)).length})).filter(r=>r.count===0).sort((a,b)=>a.name.localeCompare(b.name,'ar')).slice(0,5);const el=document.getElementById('fairPlayList');if(el)el.innerHTML=rows.map((r,i)=>`<tr><td class="rank">${i+1}</td><td>${esc(r.name)}</td><td>${teamLink(r.team)}</td><td><strong>0</strong></td></tr>`).join('')||'<tr><td colspan="4">لا توجد بيانات كافية بعد لتحديد قائمة اللعب النظيف.</td></tr>'}
function fillSelect(id,rows,valueFn,labelFn,first){const el=document.getElementById(id);if(!el)return;const current=el.value;el.innerHTML=(first?`<option value="">${esc(first)}</option>`:'')+rows.map(r=>`<option value="${esc(valueFn(r))}">${esc(labelFn(r))}</option>`).join('');if(rows.some(r=>String(valueFn(r))===String(current)))el.value=current}
function fillAdminSelects(){fillSelect('newTeamGroup',data.groups,g=>g.id,g=>g.name,'اختار المجموعة');fillSelect('newPlayerTeam',data.teams,t=>t.id,t=>t.name,'اختار الفريق');fillSelect('matchHome',data.teams,t=>t.id,t=>t.name,'اختار الفريق الأول');fillSelect('matchAway',data.teams,t=>t.id,t=>t.name,'اختار الفريق الثاني');fillSelect('eventMatch',data.matches,m=>m.id,m=>`${team(m.home_team_id).name} — ${team(m.away_team_id).name} (${formatDate(m.scheduled_at)})`,'اختار المباراة');fillEventTeam();fillEventPlayers()}
function fillEventTeam(){const m=match(document.getElementById('eventMatch')?.value);const teams=m?[team(m.home_team_id),team(m.away_team_id)]:data.teams;fillSelect('eventTeam',teams,t=>t.id,t=>t.name,'اختار الفريق');fillEventPlayers()}
function fillEventPlayers(){const tid=document.getElementById('eventTeam')?.value;const ps=data.players.filter(p=>String(p.team_id)===String(tid)&&p.active!==false);fillSelect('eventPlayer',ps,p=>p.id,p=>p.full_name,'اختار اللاعب');const assist=document.getElementById('eventAssist');if(assist){const current=assist.value;assist.innerHTML='<option value="">بدون أسيست</option>'+ps.map(p=>`<option value="${esc(p.id)}">${esc(p.full_name)}</option>`).join('');if(ps.some(p=>String(p.id)===String(current)))assist.value=current}}
const lineupPositions={
 '2-2-1':['المدافع الأيمن','المدافع الأيسر','وسط أيمن','وسط أيسر','مهاجم'],
 '2-1-2':['المدافع الأيمن','المدافع الأيسر','وسط','مهاجم أيمن','مهاجم أيسر'],
 '1-2-2':['مدافع','وسط أيمن','وسط أيسر','مهاجم أيمن','مهاجم أيسر'],
 '1-3-1':['مدافع','وسط أيمن','وسط','وسط أيسر','مهاجم'],
 '3-1-1':['المدافع الأيمن','مدافع أوسط','المدافع الأيسر','وسط','مهاجم'],
 '3-2':['المدافع الأيمن','مدافع أوسط','المدافع الأيسر','مهاجم أيمن','مهاجم أيسر'],
 '2-3':['المدافع الأيمن','المدافع الأيسر','مهاجم أيمن','مهاجم أوسط','مهاجم أيسر'],
 '1-4':['مدافع','وسط أيمن','وسط أيمن متقدم','وسط أيسر متقدم','وسط أيسر'],
 '4-1':['المدافع الأيمن','مدافع أيمن أوسط','مدافع أيسر أوسط','المدافع الأيسر','مهاجم']
};
function renderLineupPositionFields(){const box=document.getElementById('lineupPositionFields');if(!box)return;const formation=document.getElementById('lineupFormation')?.value||'2-2-1';box.innerHTML=(lineupPositions[formation]||lineupPositions['2-2-1']).map((label,i)=>`<label>${label}<select id="lineupPlayer${i}" required><option value="">اختار اللاعب</option></select></label>`).join('');fillLineupPlayers();}
function fillLineupPlayers(){const tid=document.getElementById('lineupTeam')?.value;const ps=data.players.filter(p=>String(p.team_id)===String(tid)&&p.active!==false&&p.id&&!String(p.id).startsWith('sheet-'));for(let i=0;i<5;i++){const el=document.getElementById('lineupPlayer'+i);if(!el)continue;const old=el.value;el.innerHTML='<option value="">اختار اللاعب</option>'+ps.map(p=>`<option value="${esc(p.id)}">${esc(p.full_name)}</option>`).join('');if(ps.some(p=>String(p.id)===String(old)))el.value=old;}}
function fillLineupForm(){fillSelect('lineupTeam',data.teams,t=>t.id,t=>t.name,'اختار الفريق');renderLineupPositionFields();}
function renderEvents(){const el=document.getElementById('eventLog');if(!el)return;el.innerHTML=data.events.slice().reverse().slice(0,20).map(e=>`<div class="event-item"><span class="event-minute">${esc(e.minute??'—')}${e.added_time?`+${esc(e.added_time)}`:''}′</span><span class="event-pill">${esc(eventLabel(e))}</span><span>${player(e.player_id)?playerLink(player(e.player_id)):`<strong>${esc(e.player_name||'غير محدد')}</strong>`} · ${esc(team(e.team_id).name)}${e.assist_player_name||player(e.assist_player_id)?` · أسيست: ${esc(player(e.assist_player_id)?.full_name||e.assist_player_name)}`:''}</span></div>`).join('')||'<p class="muted small">لم يتم تسجيل أي أحداث حتى الآن.</p>'}
function renderUnassignedPlayers(){const el=document.getElementById('unassignedPlayers');if(!el)return;const ps=data.players.filter(p=>p.active!==false).slice().sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));setText('unassignedPlayerCount',ps.length);el.innerHTML=ps.map(p=>`<article class="player-card">${playerPhoto(p)}<strong>${esc(p.full_name)}</strong><small>${p.is_captain?'قائد الفريق': 'لاعب'} · ${p.team_id?esc(team(p.team_id).name):'لم يُوزّع على فريق بعد'}</small></article>`).join('')||'<div class="empty">ما كايناش تسجيلات جديدة حالياً.</div>';const notice=document.getElementById('sheetNotice');if(notice)notice.textContent=sheetLoaded?'تظهر هنا التسجيلات القادمة من الاستمارة ولاعبو قاعدة البيانات. رقم الهاتف لا يُعرض.':'تظهر هنا جميع التسجيلات الموجودة في قاعدة البيانات.'}function fillPhaseMatchSelect(){const el=document.getElementById('phaseMatch');if(!el)return;const old=el.value;el.innerHTML='<option value="">اختار المباراة للتحكم فالحالة</option>'+data.matches.map(m=>`<option value="${esc(m.id)}">${esc(team(m.home_team_id).name)} — ${esc(team(m.away_team_id).name)}</option>`).join('');if(data.matches.some(m=>String(m.id)===String(old)))el.value=old;const box=document.getElementById('phaseControls');if(box)box.hidden=!el.value}
function renderMatchDetail(){
 const el=document.getElementById('matchDetail');if(!el)return;
 const id=new URLSearchParams(location.search).get('id'),m=match(id);
 if(!m){el.innerHTML='<div class="empty">المباراة غير موجودة.</div>';return}
 const h=team(m.home_team_id),a=team(m.away_team_id);
 const events=data.events.filter(e=>String(e.match_id)===String(m.id)).sort((x,y)=>(Number(x.minute)||0)-(Number(y.minute)||0)||(Number(x.added_time)||0)-(Number(y.added_time)||0));
 const seasonStats=t=>{
  const played=data.matches.filter(x=>x.status==='finished'&&(String(x.home_team_id)===String(t.id)||String(x.away_team_id)===String(t.id)));
  let wins=0,draws=0,losses=0,goalsFor=0,goalsAgainst=0;
  for(const x of played){const isHome=String(x.home_team_id)===String(t.id),gf=Number(isHome?x.home_score:x.away_score)||0,ga=Number(isHome?x.away_score:x.home_score)||0;goalsFor+=gf;goalsAgainst+=ga;if(gf>ga)wins++;else if(gf<ga)losses++;else draws++;}
  const teamEvents=data.events.filter(e=>String(e.team_id)===String(t.id));
  return {played:played.length,wins,draws,losses,goalsFor,goalsAgainst,yellow:teamEvents.filter(e=>(e.type||e.event_type)==='yellow').length,red:teamEvents.filter(e=>['red','second_yellow'].includes(e.type||e.event_type)).length};
 };
 const hs=seasonStats(h),as=seasonStats(a);
 const singleStat=(label,value)=>`<div class="match-stat-single-line"><span>${esc(value)}</span><small>${esc(label)}</small></div>`;
 const card=(t,st)=>`<article class="match-stat-card"><h3>${esc(t.name)}</h3>${singleStat('المباريات',st.played)}${singleStat('الانتصارات',st.wins)}${singleStat('التعادلات',st.draws)}${singleStat('الخسارات',st.losses)}${singleStat('الأهداف المسجلة',st.goalsFor)}${singleStat('الأهداف المستقبلة',st.goalsAgainst)}${singleStat('البطاقات الصفراء',st.yellow)}${singleStat('البطاقات الحمراء',st.red)}</article>`;
 const matchCards=teamId=>({yellow:events.filter(e=>String(e.team_id)===String(teamId)&&(e.type||e.event_type)==='yellow').length,red:events.filter(e=>String(e.team_id)===String(teamId)&&['red','second_yellow'].includes(e.type||e.event_type)).length});
 const hc=matchCards(h.id),ac=matchCards(a.id);
 el.innerHTML=`<section class="match-detail-hero" data-live-match="${esc(m.id)}"><a href="matches.html" class="back-link">← جميع المباريات</a><div class="match-meta"><span>${esc(stageLabel(m))}</span><span class="status ${esc(m.status||'upcoming')}">${statusLabel(m)}</span></div><div class="match-detail-score"><div><a class="match-team-detail-link" href="team.html?id=${encodeURIComponent(h.id)}">${teamLogo(h,true)}<strong>${esc(h.name)}</strong></a></div><div class="detail-score">${m.status==='upcoming'||m.status==='postponed'?'VS':`${mainScoreMarkup(m)}`}<small>${esc(m.scheduled_at?formatDate(m.scheduled_at):'سيُعلن عن الموعد لاحقاً')}${m.status==='live'?`<b class="live-timer">● ${esc(displayTimer(m))} <small>${esc(displayMinute(m))}′</small></b>`:''}</small></div><div><a class="match-team-detail-link" href="team.html?id=${encodeURIComponent(a.id)}">${teamLogo(a,true)}<strong>${esc(a.name)}</strong></a></div></div></section><section class="section-block"><div class="section-heading"><div><h2>أحداث المباراة</h2><p>الأهداف والبطاقات حسب الدقيقة.</p></div></div><div class="match-timeline">${events.map(e=>`<div class="event-item"><span class="event-minute">${e.minute==null?'—':esc(e.minute)}${e.added_time?`+${esc(e.added_time)}`:''}′</span><span class="event-pill">${esc(eventLabel(e))}</span><span>${player(e.player_id)?playerLink(player(e.player_id)):`<strong>${esc(e.player_name||'لاعب')}</strong>`} · ${esc(team(e.team_id).name)}${e.assist_player_name||player(e.assist_player_id)?` · أسيست: ${esc(player(e.assist_player_id)?.full_name||e.assist_player_name)}`:''}</span></div>`).join('')||'<div class="empty">لا توجد أحداث مسجلة حتى الآن.</div>'}</div></section><section class="section-block"><div class="section-heading"><div><h2>إحصائيات المباراة والفريقين</h2><p>الحصيلة العامة من المباريات المنتهية، وبطاقات هذه المواجهة.</p></div></div><div class="match-stats-grid">${card(h,hs)}${card(a,as)}</div><div class="match-stat-card current-match-stats"><h3>إحصائيات هذه المباراة</h3>${statLine('الأهداف',Number(m.home_score)||0,Number(m.away_score)||0)}${statLine('البطاقات الصفراء',hc.yellow,ac.yellow)}${statLine('البطاقات الحمراء',hc.red,ac.red)}</div></section>`;
}
function statLine(label,left,right){return `<div class="match-stat-line"><span>${left}</span><small>${label}</small><span>${right}</span></div>`}
function renderAll(){renderStats();renderMatches();renderStandings();renderTeams();renderUnassignedPlayers();renderTeamDetail();renderPlayerDetail();renderScorers();fillAdminSelects();fillLineupForm();renderEvents();renderMatchDetail();fillPhaseMatchSelect()}
async function loadCloud(){
 if(!sb){cloudMode=false;return false;}
 try{
  // Load core tables independently from match_events: a broken event schema must not disable team/player administration.
  const [g,t,p,m]=await Promise.all([
   sb.from('groups').select('*').order('id'),
   sb.from('teams').select('*').order('name'),
   sb.from('players').select('*').order('full_name'),
   sb.from('matches').select('*').order('scheduled_at')
  ]);
  for(const r of [g,t,p,m])if(r.error)throw r.error;
  data.groups=(g.data||[]).map(x=>({id:x.id,name:x.name}));
  data.teams=(t.data||[]).map(x=>({id:x.id,name:x.name,group_id:x.group_id,short_name:x.short_name||x.name.slice(0,1),logo_url:x.logo_url}));
  data.players=(p.data||[]).map(x=>({id:x.id,team_id:x.team_id,full_name:x.full_name,shirt_number:x.shirt_number,photo_url:x.photo_url,active:x.active,is_captain:!!x.is_captain,created_at:x.created_at}));
  data.matches=(m.data||[]).map(x=>({id:x.id,home_team_id:x.home_team_id,away_team_id:x.away_team_id,group_id:x.group_id,stage:x.stage,scheduled_at:x.scheduled_at,status:x.status,home_score:x.home_score,away_score:x.away_score,minute:x.current_minute,phase:x.match_phase||'upcoming',phase_started_at:x.phase_started_at||null,phase_elapsed_seconds:Number(x.phase_elapsed_seconds)||0,penalty_home_score:x.penalty_home_score??null,penalty_away_score:x.penalty_away_score??null}));
  if(sheetLoaded)data.players=data.players.concat(sheetPlayers);else await loadSheetPlayers();
  const ev=await sb.from('match_events').select('*').order('created_at');
  if(ev.error){
   console.warn('تعذر تحميل أحداث المباريات؛ بقيت إدارة الفرق واللاعبين متاحة:',ev.error);
   data.events=[];
   setText('connectionNotice','الاتصال الأساسي خدام، لكن جدول أحداث المباريات يحتاج تحديثاً. شغّل ملف supabase_admin_repair.sql من SQL Editor.');
  }else{
   data.events=(ev.data||[]).map(x=>({id:x.id,match_id:x.match_id,team_id:x.team_id,player_id:x.player_id,player_name:x.player_name,type:x.event_type,minute:x.minute,added_time:x.added_time,description:x.description,goal_method:x.goal_method,assist_player_id:x.assist_player_id,assist_player_name:x.assist_player_name}));
   setText('connectionNotice',isStaff()?`تم الاتصال بقاعدة البيانات بصلاحية ${currentRole}.`:'تم الاتصال بقاعدة البيانات.');
  }
  const lr=await sb.from('team_lineups').select('*').order('created_at');
  if(lr.error){console.warn('جدول التشكيلات غير جاهز بعد:',lr.error.message);data.lineups=[];}else{data.lineups=lr.data||[];}
  cloudMode=true;
  return true;
 }catch(err){
  console.error('فشل تحميل بيانات الإدارة الأساسية:',err);
  cloudMode=false;
  setText('connectionNotice','تعذر الاتصال بالجداول الأساسية: '+(err.message||'راجع إعدادات Supabase.'));
  return false;
 }
}
async function getRole(user){currentRole=null;if(!user||!sb)return;const {data:p,error}=await sb.from('profiles').select('role').eq('id',user.id).maybeSingle();if(error){console.error(error);return}currentRole=p?.role||'viewer'}
async function refreshAuth(){if(!sb)return;const {data:{session}}=await sb.auth.getSession();currentUser=session?.user||null;await getRole(currentUser)}
function isStaff(){return !!currentUser&&['admin','editor'].includes(currentRole)}
function protectAdmin(){const page=location.pathname.split('/').pop();if(!page.startsWith('admin'))return;const notice=document.getElementById('connectionNotice');const loginForm=document.getElementById('loginForm');const links=document.getElementById('adminLinks');const welcome=document.getElementById('adminWelcome');const reg=document.getElementById('registrationForms');const events=document.getElementById('eventAdminForms');const authPanel=document.getElementById('authPanel');const logout=document.getElementById('logoutBtn');if(!supabaseReady){if(notice)notice.textContent='Supabase غير مهيأ. راجع supabase.env.example.js.';if(loginForm)loginForm.hidden=true;return}if(logout)logout.hidden=!currentUser;if(isStaff()){if(loginForm)loginForm.hidden=true;if(logout)logout.hidden=false;if(links)links.hidden=false;if(welcome)welcome.hidden=false;if(reg)reg.hidden=false;if(events)events.hidden=false;if(notice)notice.textContent=`تم تسجيل الدخول بصلاحية ${currentRole}. البيانات متصلة بقاعدة Supabase.`;if(authPanel){const msg=document.getElementById('authMessage');if(msg)msg.textContent=`مرحباً ${currentUser.email}`}}else{if(links)links.hidden=true;if(welcome)welcome.hidden=true;if(reg)reg.hidden=true;if(events)events.hidden=true;if(notice)notice.textContent=currentUser?'هذا الحساب لا يملك صلاحية الإدارة.':'سجل الدخول بحساب اللجنة المنظمة للوصول إلى أدوات الإدارة.';if(authPanel&&loginForm)loginForm.hidden=false;if(page!=='admin.html')setTimeout(()=>{location.href='admin.html'},500)}}
async function insertOrUpdateMatch(m){const patch={home_score:m.home_score,away_score:m.away_score,status:m.status,current_minute:m.minute};if(m.phase)patch.match_phase=m.phase;let result=await sb.from('matches').update(patch).eq('id',m.id);if(result.error&&/match_phase.*(schema cache|column)|column.*match_phase/i.test(result.error.message||'')){const fallback={...patch};delete fallback.match_phase;result=await sb.from('matches').update(fallback).eq('id',m.id);console.warn('تم تحديث النتيجة بدون match_phase؛ شغّل migration لإتاحة أزرار مراحل المباراة.')}if(result.error)throw result.error}
async function uploadTournamentImage(file, folder){
 if(!file) return null;
 if(!file.type || !file.type.startsWith('image/')) throw new Error('اختار ملف صورة صالح.');
 if(file.size > 5 * 1024 * 1024) throw new Error('حجم الصورة خاصو ما يفوتش 5MB.');
 if(!sb) throw new Error('قاعدة البيانات غير متصلة.');
 const safeName=(file.name||'image').normalize('NFKD').replace(/[^a-zA-Z0-9._-]/g,'-').replace(/-+/g,'-').slice(-80)||'image';
 const path=`${folder}/${Date.now()}-${Math.random().toString(36).slice(2,9)}-${safeName}`;
 const {data:uploaded,error}=await sb.storage.from('tournament-images').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});
 if(error) throw new Error('فشل رفع الصورة. تأكد من إعداد Storage: '+error.message);
 const {data:publicData}=sb.storage.from('tournament-images').getPublicUrl(uploaded.path);
 if(!publicData?.publicUrl) throw new Error('ترفع الملف ولكن تعذر إنشاء رابط الصورة.');
 return publicData.publicUrl;
}
function setupImagePreview(inputId, previewId){
 const input=document.getElementById(inputId), preview=document.getElementById(previewId);
 if(!input||!preview)return;
 input.addEventListener('change',()=>{
  const file=input.files?.[0];
  if(!file){preview.hidden=true;preview.removeAttribute('src');return;}
  if(!file.type.startsWith('image/')){toast('اختار ملف صورة صالح.');input.value='';preview.hidden=true;return;}
  if(file.size>5*1024*1024){toast('حجم الصورة خاصو ما يفوتش 5MB.');input.value='';preview.hidden=true;return;}
  preview.src=URL.createObjectURL(file);preview.hidden=false;
 });
}
