const addTeamForm=document.getElementById('addTeamForm');if(addTeamForm)addTeamForm.addEventListener('submit',async e=>{e.preventDefault();if(!isStaff()||!cloudMode){toast('سجل الدخول بحساب إداري وتأكد من اتصال قاعدة البيانات.');return}const name=document.getElementById('newTeamName').value.trim(),group_id=document.getElementById('newTeamGroup').value,logoFile=document.getElementById('newTeamLogo').files?.[0]||null,short_name=document.getElementById('newTeamShort').value.trim()||name.slice(0,2);if(!group_id){toast('اختار المجموعة.');return}try{const submit=e.target.querySelector('button[type=submit]');if(submit){submit.disabled=true;submit.textContent='جاري حفظ الفريق...'}const logo_url=await uploadTournamentImage(logoFile,'teams');const {data:r,error}=await sb.from('teams').insert({name,group_id,logo_url,short_name}).select('*').single();if(error)throw error;data.teams.push({id:r.id,name:r.name,group_id:r.group_id,logo_url:r.logo_url,short_name:r.short_name});renderAll();e.target.reset();document.getElementById('newTeamLogoPreview').hidden=true;toast('تم تسجيل الفريق بنجاح.')}catch(err){console.error(err);toast('تعذر تسجيل الفريق: '+err.message)}finally{const submit=e.target.querySelector('button[type=submit]');if(submit){submit.disabled=false;submit.textContent='حفظ الفريق'}}});
const addPlayerForm=document.getElementById('addPlayerForm');if(addPlayerForm)addPlayerForm.addEventListener('submit',async e=>{e.preventDefault();if(!isStaff()||!cloudMode){toast('سجل الدخول بحساب إداري وتأكد من اتصال قاعدة البيانات.');return}const full_name=document.getElementById('newPlayerName').value.trim(),team_id=document.getElementById('newPlayerTeam').value,is_captain=document.getElementById('newPlayerRole').value==='captain',photoFile=document.getElementById('newPlayerPhoto').files?.[0]||null;if(!team_id){toast('اختار الفريق.');return}try{const submit=e.target.querySelector('button[type=submit]');if(submit){submit.disabled=true;submit.textContent='جاري حفظ اللاعب...'}const photo_url=await uploadTournamentImage(photoFile,'players');let payload={full_name,team_id,shirt_number:null,photo_url,active:true,is_captain};let result=await sb.from('players').insert(payload).select('*').single();let captainColumnMissing=false;if(result.error&&/is_captain.*(column|schema cache)|column.*is_captain/i.test(result.error.message||'')){console.warn('قاعدة البيانات لا تحتوي is_captain؛ إعادة المحاولة بدون هذا الحقل.');const fallback={...payload};delete fallback.is_captain;result=await sb.from('players').insert(fallback).select('*').single();if(!result.error){payload=fallback;captainColumnMissing=true;}}if(result.error)throw result.error;data.players.push({id:result.data.id,...payload,is_captain:!!payload.is_captain});renderAll();e.target.reset();document.getElementById('newPlayerPhotoPreview').hidden=true;toast(captainColumnMissing?'تسجل اللاعب، لكن شغّل ملف supabase_admin_repair.sql لتفعيل صفة قائد الفريق.':'تم تسجيل اللاعب بنجاح.');}catch(err){console.error(err);toast('تعذر تسجيل اللاعب: '+err.message)}finally{const submit=e.target.querySelector('button[type=submit]');if(submit){submit.disabled=false;submit.textContent='حفظ اللاعب'}}});
const eventType=document.getElementById('eventType');if(eventType)eventType.addEventListener('change',()=>{const goals=['goal','own_goal'].includes(eventType.value);const box=document.getElementById('goalOptions');if(box)box.hidden=!goals});
const eventMatch=document.getElementById('eventMatch');if(eventMatch)eventMatch.addEventListener('change',fillEventTeam);const eventTeam=document.getElementById('eventTeam');if(eventTeam)eventTeam.addEventListener('change',fillEventPlayers);
const matchPhaseSelect=document.getElementById('phaseMatch');if(matchPhaseSelect)matchPhaseSelect.addEventListener('change',()=>{const mm=match(matchPhaseSelect.value);const box=document.getElementById('phaseControls');if(box)box.hidden=!mm;document.querySelectorAll('[data-match-phase]').forEach(b=>{if(b.dataset.matchPhase==='penalties'){b.disabled=!mm||mm.status!=='finished'||!tiedMatch(mm);b.title=b.disabled?'متاحة فقط بعد نهاية المباراة وعند التعادل':'تسجيل نتيجة ضربات الجزاء'}else if(b.dataset.matchPhase==='finished'){b.disabled=!!mm&&mm.status==='finished'&&phaseOf(mm)==='finished'} });});
document.querySelectorAll('[data-match-phase]').forEach(btn=>btn.addEventListener('click',async()=>{if(!isStaff()||!cloudMode){toast('خاصك تدخل بحساب إداري.');return}const mm=match(document.getElementById('phaseMatch')?.value);if(!mm){toast('اختار المباراة أولاً.');return}const phase=btn.dataset.matchPhase;if(phase==='extra_time'){toast('ماكايناش أشواط إضافية فهاد الدوري.');return}if(phase==='penalties'){if(mm.status!=='finished'){toast('سالي المباراة أولاً، ومن بعد تقدر تسجل ضربات الجزاء إلا كان التعادل.');return}if(!tiedMatch(mm)){toast('ضربات الجزاء متاحة فقط إذا كانت النتيجة متعادلة.');return}const homeRaw=prompt(`نتيجة ضربات الجزاء — ${team(mm.home_team_id).name}\nدخل عدد الأهداف:`,`0`);if(homeRaw===null)return;const awayRaw=prompt(`نتيجة ضربات الجزاء — ${team(mm.away_team_id).name}\nدخل عدد الأهداف:`,`0`);if(awayRaw===null)return;const ph=Number(homeRaw),pa=Number(awayRaw);if(!Number.isInteger(ph)||ph<0||!Number.isInteger(pa)||pa<0||ph===pa){toast('دخل نتيجتين صحيحتين ومختلفتين لضربات الجزاء.');return}const patch={penalty_home_score:ph,penalty_away_score:pa,status:'finished',match_phase:'penalties',current_minute:45,phase_started_at:null};const result=await sb.from('matches').update(patch).eq('id',mm.id);if(result.error){console.error(result.error);toast('تعذر حفظ نتيجة ضربات الجزاء. شغّل ملف supabase_migration_penalties.sql ثم أعد المحاولة.');return}Object.assign(mm,{penalty_home_score:ph,penalty_away_score:pa,status:'finished',phase:'penalties',minute:45,phase_started_at:null});await loadCloud();renderAll();toast('تحفظات نتيجة ضربات الجزاء وتعرضات تحت النتيجة.');return}if(['first_half','second_half'].includes(phase)&&!scheduledReached(mm)){toast('مايمكنش تبدا المباراة قبل الموعد المحدد.');return}if(phase==='second_half'&&phaseOf(mm)!=='half_time'){toast('خاصك تسجل نهاية الشوط الأول قبل بداية الشوط الثاني.');return}if(phase==='half_time'&&phaseOf(mm)!=='first_half'){toast('نهاية الشوط الأول متاحة أثناء الشوط الأول فقط.');return}if(phase==='finished'&&phaseOf(mm)==='upcoming'){toast('مايمكنش تنهي مباراة ما بداتش.');return}const status=phase==='finished'?'finished':phase==='upcoming'?'upcoming':'live';const minute=phase==='first_half'?0:phase==='half_time'?20:phase==='second_half'?20:phase==='extra_time'||phase==='penalties'||phase==='finished'?45:(mm.minute||0);const elapsed=phase==='second_half'?0:phase==='extra_time'?0:0;const startedAt=['first_half','second_half','extra_time'].includes(phase)?new Date().toISOString():null;const patch={status,match_phase:phase,current_minute:minute,phase_started_at:startedAt};let result=await sb.from('matches').update(patch).eq('id',mm.id);if(result.error&&/phase_started_at|match_phase/i.test(result.error.message||'')){delete patch.phase_started_at;result=await sb.from('matches').update(patch).eq('id',mm.id)}if(result.error){console.error(result.error);toast('تعذر تحديث حالة المباراة: '+result.error.message);return}mm.status=status;mm.phase=phase;mm.minute=minute;mm.phase_started_at=startedAt;mm.phase_elapsed_seconds=elapsed;await loadCloud();renderAll();toast('تم تحديث حالة المباراة.') }));
const eventForm=document.getElementById('eventForm');if(eventForm)eventForm.addEventListener('submit',async e=>{e.preventDefault();if(!isStaff()||!cloudMode){toast('سجل الدخول بحساب إداري وتأكد من اتصال قاعدة البيانات.');return}const m=match(document.getElementById('eventMatch').value),type=document.getElementById('eventType').value,team_id=document.getElementById('eventTeam').value,player_id=document.getElementById('eventPlayer').value,addedRaw=document.getElementById('eventAddedTime').value,goal_method=document.getElementById('goalMethod').value,assist_player_id=document.getElementById('eventAssist').value||null,description=document.getElementById('eventDescription').value.trim()||null;if(!m||!team_id||!player_id){toast('اختار المباراة والفريق واللاعب.');return}if(!scheduledReached(m)||m.status!=='live'){toast('الأحداث متاحة فقط بعد موعد المباراة وبعد الضغط على بداية المباراة.');return}if(![m.home_team_id,m.away_team_id].some(id=>String(id)===String(team_id))){toast('الفريق المختار غير مشارك في هذه المباراة.');return}const minute=liveMinute(m),added_time=addedRaw?Number(addedRaw):null,p=player(player_id),assist=player(assist_player_id);if(!Number.isInteger(minute)||minute<1||minute>45){toast('المؤقت مازال ما وصلش للدقيقة الأولى أو المباراة سالات؛ تحقق من حالة المباراة.');return}if(added_time!==null&&(!Number.isInteger(added_time)||added_time<0||added_time>15)){toast('الوقت بدل الضائع خاصو يكون بين 0 و15.');return}let scoreTeam=team_id;if(type==='own_goal')scoreTeam=String(team_id)===String(m.home_team_id)?m.away_team_id:m.home_team_id;const payload={match_id:m.id,team_id,player_id,player_name:p?.full_name||null,event_type:type,minute,added_time,description,goal_method:['goal','own_goal'].includes(type)?goal_method:null,assist_player_id:type==='goal'?assist_player_id:null,assist_player_name:type==='goal'?(assist?.full_name||null):null,created_by:currentUser.id};try{let eventResult=await sb.from('match_events').insert(payload).select('*').single();if(eventResult.error&&/Could not find the '([^']+)' column of 'match_events' in the schema cache/i.test(eventResult.error.message||'')){const missing=eventResult.error.message.match(/Could not find the '([^']+)' column/);const fallback={...payload};['assist_player_id','assist_player_name','goal_method'].forEach(k=>delete fallback[k]);if(missing)delete fallback[missing[1]];console.warn('إعادة محاولة حفظ الحدث بدون أعمدة الاختيارات الإضافية؛ العمود الناقص:',missing?.[1]);eventResult=await sb.from('match_events').insert(fallback).select('*').single();}if(eventResult.error)throw eventResult.error;const r=eventResult.data;data.events.push({...r,type:r.event_type});if(['goal','own_goal'].includes(type)){if(String(scoreTeam)===String(m.home_team_id))m.home_score=Number(m.home_score||0)+1;else m.away_score=Number(m.away_score||0)+1;if(m.status==='upcoming')m.status='live';if(minute)m.minute=minute;await insertOrUpdateMatch(m)}await loadCloud();renderAll();e.target.reset();const box=document.getElementById('goalOptions');if(box)box.hidden=false;toast('تم تسجيل الحدث وتحديث النتيجة.')}catch(err){console.error(err);toast('تعذر تسجيل الحدث: '+err.message)}});
const loginForm=document.getElementById('loginForm');if(loginForm)loginForm.addEventListener('submit',async e=>{e.preventDefault();if(!sb){toast('راجع إعدادات Supabase أولاً.');return}const email=document.getElementById('loginEmail').value.trim(),password=document.getElementById('loginPassword').value;const {error}=await sb.auth.signInWithPassword({email,password});if(error){toast('فشل تسجيل الدخول: '+error.message);return}await refreshAuth();await loadCloud();protectAdmin();renderAll();if(isStaff()&&location.pathname.split('/').pop()==='admin.html'){location.href='admin-events.html';return}toast(isStaff()?'تم تسجيل الدخول بنجاح.':'الحساب لا يملك صلاحية الإدارة.')});
