const lineupForm=document.getElementById('lineupForm');if(lineupForm)lineupForm.addEventListener('submit',async e=>{e.preventDefault();if(!isStaff()||!cloudMode){toast('خاصك تدخل بحساب إداري.');return;}const tid=document.getElementById('lineupTeam').value,formation=document.getElementById('lineupFormation').value,ids=Array.from({length:5},(_,i)=>document.getElementById('lineupPlayer'+i)?.value||'');if(!tid||ids.some(x=>!x)){toast('اختار الفريق و5 لاعبين للمراكز.');return;}if(new Set(ids).size!==5){toast('مايمكنش تختار نفس اللاعب أكثر من مرة.');return;}if(ids.some(id=>!data.players.some(p=>String(p.id)===String(id)&&String(p.team_id)===String(tid)))){toast('تأكد أن اللاعبين تابعين للفريق المختار.');return;}try{const del=await sb.from('team_lineups').delete().eq('team_id',tid);if(del.error)throw del.error;const rows=ids.map((id,i)=>({team_id:tid,player_id:id,position:(lineupPositions[formation]||lineupPositions['2-2-1'])[i],slot:i,formation,created_by:currentUser.id}));const ins=await sb.from('team_lineups').insert(rows);if(ins.error)throw ins.error;await loadCloud();renderAll();toast('تحفظات تشكيلة الفريق.');}catch(err){console.error(err);toast('تعذر حفظ التشكيلة: '+err.message);}});
(async function init(){if(supabaseReady){await loadCloud();await loadSheetPlayers();await refreshAuth();protectAdmin();renderAll();if(isStaff()&&location.pathname.split('/').pop()==='admin.html'){location.replace('admin-events.html');return;}sb.channel('tournament-live').on('postgres_changes',{event:'*',schema:'public',table:'matches'},async()=>{await loadCloud();await loadSheetPlayers();renderAll()}).on('postgres_changes',{event:'*',schema:'public',table:'match_events'},async()=>{await loadCloud();await loadSheetPlayers();renderAll()}).on('postgres_changes',{event:'*',schema:'public',table:'teams'},async()=>{await loadCloud();await loadSheetPlayers();renderAll()}).on('postgres_changes',{event:'*',schema:'public',table:'players'},async()=>{await loadCloud();await loadSheetPlayers();renderAll()}).subscribe()}else{await loadSheetPlayers();renderAll();if(location.pathname.split('/').pop().startsWith('admin'))protectAdmin()}})();
const addMatchForm=document.getElementById('addMatchForm');if(addMatchForm)addMatchForm.addEventListener('submit',async e=>{e.preventDefault();if(!isStaff()||!cloudMode){toast('سجل الدخول بحساب إداري وتأكد من اتصال قاعدة البيانات.');return}const home=document.getElementById('matchHome').value,away=document.getElementById('matchAway').value,date=document.getElementById('matchDate').value,stage=document.getElementById('matchStage').value;if(!home||!away||home===away){toast('اختار فريقين مختلفين.');return}const h=team(home),a=team(away);try{const payload={home_team_id:home,away_team_id:away,group_id:stage==='groups'&&String(h.group_id)===String(a.group_id)?h.group_id:null,stage,scheduled_at:new Date(date).toISOString(),status:'upcoming',home_score:0,away_score:0};const {data:r,error}=await sb.from('matches').insert(payload).select('*').single();if(error)throw error;data.matches.push({id:r.id,...payload,minute:null});renderAll();e.target.reset();toast('تمت إضافة المباراة بنجاح.')}catch(err){console.error(err);toast('تعذر إضافة المباراة: '+err.message)}});


setInterval(()=>{if(document.getElementById('matchDetail'))renderMatchDetail();document.querySelectorAll('.live-timer').forEach(el=>{const m=match(new URLSearchParams(location.search).get('id'));if(m)el.textContent='● '+displayMinute(m)+'′'});document.querySelectorAll('[data-live-clock]').forEach(el=>{const m=match(el.dataset.liveClock);if(m)el.textContent=displayMinute(m)+'′'})},1000);

// Refresh visible match timers every second; refresh server state periodically so all viewers stay aligned.
setInterval(()=>{document.querySelectorAll('.live-timer').forEach(el=>{const card=el.closest('[data-live-match]');if(card){const mm=match(card.dataset.liveMatch);if(mm)el.innerHTML='● '+esc(displayTimer(mm))+' <small>'+esc(displayMinute(mm))+'′</small>';}});},1000);
